#!/usr/bin/env bash
set -euo pipefail
# run_file_transfer_bench.sh — bulk transfer through the tunnel, across sizes.
#
# Prerequisites: VPN tunnel is up, vpn_ns1 and vpn_ns2 namespaces exist
# Usage: sudo ip netns exec vpn_ns2 bash benchmark/run_file_transfer_bench.sh <mode>
#
# The measurement itself lives in transfer_bench.py; this script only places the
# two ends in the right namespaces. Nothing is written to disk at either end —
# the server streams generated bytes and the client hashes and discards them, so
# the figure is the tunnel's rate rather than the filesystem's, and a 1 GB
# transfer needs no free space. See transfer_bench.py for why that matters.
#
# Sizes and repetitions:
#   PQVPN_BENCH_SIZES="1K 1M 100M"   (default: 1K 100K 1M 10M 100M 500M 1G)
#   PQVPN_BENCH_REPS=3

MODE="${1:-unknown}"
BENCH_DIR="$(cd "$(dirname "$0")" && pwd)"
PDIR="$(dirname "$BENCH_DIR")"
PY="${PDIR}/.venv/bin/python3"
[ -x "$PY" ] || PY=python3
RESULTS_DIR="${PQVPN_RESULTS_DIR:-${BENCH_DIR}/results}"
SERVER_NETNS="vpn_ns1"
SERVER_IP="10.8.0.1"
PORT=9998

mkdir -p "${RESULTS_DIR}"
CSV="${RESULTS_DIR}/file_transfer_${MODE}.csv"

# A server left behind by an interrupted run would still be listening on this
# port, and the readiness check below cannot tell it apart from a fresh one --
# so the sweep would silently measure against a stale process.
ip netns exec "${SERVER_NETNS}" pkill -f "transfer_bench.py --serve" 2>/dev/null || true
sleep 0.3

# The server runs in the server namespace and is reached over the tunnel.
ip netns exec "${SERVER_NETNS}" "$PY" "${BENCH_DIR}/transfer_bench.py" \
    --serve 0.0.0.0 "${PORT}" >/dev/null 2>&1 &
SERVER_PID=$!
cleanup() {
    kill "${SERVER_PID}" 2>/dev/null || true
    wait "${SERVER_PID}" 2>/dev/null || true
}
trap cleanup EXIT

# Wait for the listener rather than sleeping a fixed amount: a fixed sleep is
# either slower than it needs to be or occasionally too short.
for _ in $(seq 50); do
    if ip netns exec "${SERVER_NETNS}" ss -ltn 2>/dev/null | grep -q ":${PORT} "; then
        break
    fi
    sleep 0.1
done

"$PY" "${BENCH_DIR}/transfer_bench.py" \
    --client "${SERVER_IP}" "${PORT}" --mode "${MODE}" --out "${CSV}"
